// Runtime loader for the generated extension contributions (ADR-0017 S6):
// composes the ENABLED set from discovery, registers those packages' Admin
// UI (nav/routes/translations) and unregisters everything else. Called at
// Admin start and re-run whenever the Extensions screen mutates lifecycle
// state (window event pcms:extensions-changed).
import { useEffect, useSyncExternalStore } from "react";
import { apiGet } from "../api/client.js";
import { t } from "../i18n/index.js";
// GENERATED by scripts/compose-first-party.mjs emit-admin (gitignored).
import { extensionContributions } from "./contributions.generated.js";
import type { AdminContributionApi, ExtensionContribution } from "./contributions-api.js";
import {
  extensionRegistryVersion,
  registerNavSection,
  registerRoute,
  subscribeExtensionRegistry,
  unregisterExtensionContributions,
} from "./registry.js";
import { requestExtensionApi } from "./request.js";

export async function refreshExtensionContributions(
  t: (key: string, vars?: Record<string, string | number>) => string,
): Promise<void> {
  let enabled: Set<string>;
  try {
    const result = await apiGet<{ items: readonly { id: string; state: string | null }[] }>(
      "/extensions",
    );
    enabled = new Set(
      result.items.filter((entry) => entry.state === "ENABLED").map((entry) => entry.id),
    );
  } catch {
    return; // not authenticated yet — retried on the next trigger
  }
  for (const contribution of extensionContributions as readonly ExtensionContribution[]) {
    unregisterExtensionContributions(contribution.extensionId);
    if (!enabled.has(contribution.extensionId)) continue;
    const api: AdminContributionApi = {
      extensionId: contribution.extensionId,
      request: requestExtensionApi,
      t,
      nav: (section) => registerNavSection({ ...section, extensionId: contribution.extensionId }),
      route: (route) => registerRoute({ ...route, extensionId: contribution.extensionId }),
      translations: (fragment) => registerContributionTranslations(fragment),
    };
    await contribution.register(api);
  }
}

/** Window-event trigger; the Extensions screen dispatches it after any
 * lifecycle mutation so nav/routes react without a reload. */
export function watchExtensionChanges(refresh: () => Promise<void>): () => void {
  const listener = () => {
    void refresh();
  };
  window.addEventListener("pcms:extensions-changed", listener);
  return () => window.removeEventListener("pcms:extensions-changed", listener);
}

function registerContributionTranslations(fragment: {
  readonly ru: Record<string, string>;
  readonly en: Record<string, string>;
}): void {
  void import("../i18n/index.js").then((i18n) => i18n.registerTranslations(fragment));
}

/** App-level hook: composes contributions after auth and watches lifecycle
 * changes; the registry version forces the tree re-render. */
export function useExtensionContributions(authStatus: string): number {
  const version = useSyncExternalStore(subscribeExtensionRegistry, extensionRegistryVersion);
  useEffect(() => {
    if (authStatus !== "authed") return; // discovery needs a session
    void refreshExtensionContributions(t);
    return watchExtensionChanges(() => refreshExtensionContributions(t));
  }, [authStatus]);
  return version;
}
